def is_pal(s):
    t = s.lower()
    return t == t[::-1]

def fizz(n):
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append('FizzBuzz')
        elif i % 3 == 0:
            out.append('Fizz')
        elif i % 5 == 0:
            out.append('Buzz')
        else:
            out.append(str(i))
    return out

def merge(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

import bisect
def lis(a):
    t = []
    for x in a:
        k = bisect.bisect_left(t, x)
        if k == len(t):
            t.append(x)
        else:
            t[k] = x
    return len(t)
